@push("scripts")
<script>
    document.addEventListener("DOMContentLoaded", () => {
        const buttonContrast = document.getElementById("contraste");

        if(localStorage.getItem("contrast") === "enabled") {
            document.body.classList.add("contrast");
        }  

        buttonContrast.addEventListener("click", () => {
            document.body.classList.toggle("contrast");

            if(document.body.classList.contains("contrast")) {
                localStorage.setItem("contrast", "enabled");
            } else {
                localStorage.setItem("contrast", "disabled");
            }
        });
    });
</script>
@endpush
